PARAMETER_STATUS = {
    "weekly_staffing_floor": {
        "value": weekly_staffing_floor,
        "classification": "HISTORICAL_PROXY_UNVALIDATED",
        "caveat": "Historical minimum weekly active-pharmacy count; not a validated coverage standard.",
    },
    "maximum_annual_workload": {
        "value": maximum_annual_workload,
        "classification": "HISTORICAL_PROXY_UNVALIDATED",
        "caveat": "Historical maximum assignments per pharmacy; not a certified fairness ceiling.",
    },
    "weekly_h24_required": {
        "value": weekly_h24_required,
        "classification": "OBSERVED_VALUE_PRESERVED_BY_POLICY",
        "caveat": "Uniform across 53 historical blocks; preserving it is a modeling policy, not external validation.",
    },
}
for name, info in PARAMETER_STATUS.items():
    print(f"{name} = {info['value']}  [{info['classification']}]  {info['caveat']}")

PARAMETER_STATUS["h24_cycle_bounds_by_group"] = {
    "value": h24_cycle_bounds_by_group,
    "classification": "NORMATIVE_EQUAL_COUNT_POLICY",
    "caveat": "Floor/ceiling of equal H24 slot allocation per 42-pattern cycle; a hard fairness policy, not an observed eligibility fact."}

secondary_group_by_pharmacy = {}
for pharmacy_id, rows in cross_group_events.groupby("pharmacy_id"):
    observed_secondary_groups = sorted(rows["rotation_group"].unique().tolist())
    secondary_group_by_pharmacy[pharmacy_id] = {
        "primary_group": int(primary_group[pharmacy_id]),
        "historical_secondary_groups": [int(g) for g in observed_secondary_groups],
        "evidence": [
            {"week_id": r.week_id, "nT": int(r.nT), "shift_type": r.shift_type}
            for r in rows.itertuples()
        ],
    }

display(cross_group_events)
print("Secondary-eligibility candidates:", list(secondary_group_by_pharmacy))
